// ✅ Input là urgent; cập nhật query dùng để render danh sách là Transition
import { useState, useTransition } from 'react';

function SearchDemo() {
  const [input, setInput] = useState('');
  const [listQuery, setListQuery] = useState('');
  const [isPending, startTransition] = useTransition();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const next = e.target.value;
    setInput(next); // Controlled input phải cập nhật đồng bộ
    startTransition(() => {
      setListQuery(next); // Đánh dấu render HeavyList là không khẩn cấp
    });
  };

  return (
    <div>
      <input value={input} onChange={handleChange} placeholder="Tìm kiếm..." />
      {isPending && <span>Đang cập nhật kết quả...</span>}
      <HeavyList query={listQuery} aria-busy={isPending} />
    </div>
  );
}

