// ✅ Ảo hóa: Chỉ render ~15 DOM nodes nhìn thấy được trong viewport
import { useRef } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';

function VirtualizedList({ items }: { items: string[] }) {
  const parentRef = useRef<HTMLDivElement>(null);

  const rowVirtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 40, // Chiều cao ước tính mỗi dòng (px)
    overscan: 5,
  });

  return (
    <div ref={parentRef} className="h-[400px] overflow-auto border rounded-xl">
      <div style={{ height: `${rowVirtualizer.getTotalSize()}px`, width: '100%', position: 'relative' }}>
        {rowVirtualizer.getVirtualItems().map((virtualRow) => (
          <div
            key={virtualRow.index}
            className="absolute left-0 top-0 w-full h-10 px-4 flex items-center border-b"
            style={{ transform: `translateY(${virtualRow.start}px)` }}
          >
            {items[virtualRow.index]}
          </div>
        ))}
      </div>
    </div>
  );
}
